"""Publish only observed metrics and accepted server receipts."""
import json
from pathlib import Path
from experiments.native_localizer.common import atomic_json


def main():
    root=Path(__file__).parent;results=root/'results';measure=[];finished=(results/'screen-v1/evaluation.json').exists();lines=['# PCMV: one fixed-fold experiment and stronger PixelSeal deployment','','The stronger PixelSeal checkpoint was deployed as submission #3188 / public 0.6736. TrustMark and StegaStamp remain exactly as in #3054. '+('The single PixelSeal PCMV screen completed with no validation improvement; no PCMV submission was made. No extended training was launched.' if finished else 'The single PixelSeal PCMV scorer screen is in progress; no scorer improvement is claimed.')+' No full cross-validation or backbone search. GPUs 0–1 only in the second job; GPUs 2–3 reserved for the user’s other experiment.','']
    p=results/'base-candidate/evaluation.json'
    if p.exists():
        d=json.loads(p.read_text());decision=p.with_name('decision.json');selected=json.loads(decision.read_text())['selected'] if decision.exists() else d['selected_for_test'];lines+=['## Stronger checkpoint verification','',f"EMA1561 global/carrier branch, no refiner or Noiseprint inference inputs. Same 57-image development fold: {d['baseline']['all']['miou']:.6f} → **{d['summary']['all']['miou']:.6f}**, delta {d['delta']:+.6f}, paired 95% CI {d['ci95']}. Selected for test: {selected}. This checkpoint trained 113 real images plus synthetic replay; no all 170 refit. Reused fold and checkpoint selection create optimism; this is not a fresh held-out estimate.",'','The first short job completed with the earlier minority guard and produced no test predictions. Per the user’s priority to use the strongest overall model, the subsequent decision retained this checkpoint despite FG 1–5% IoU falling 0.012724→0. Global validation and public scores improved; the tiny-watermark problem remains unresolved. The original decision/evaluation artifacts are preserved.','', '| Bucket | n | Metric | Previous | Candidate |','|---|---:|---|---:|---:|']
        for group,metric in [('fg_le1','fg_iou'),('fg_1to5','fg_iou'),('fg_5to20','fg_iou'),('fg_gt20','fg_iou'),('clean_le1','clean_iou'),('clean_1to5','clean_iou'),('wm_over50','clean_iou')]:
            a,b=d['baseline'][group],d['summary'][group];lines.append(f"| {group} | {b['n']} | {metric} | {a[metric]:.6f} | {b[metric]:.6f} |")
        measure.append({'family':'pixelseal','name':'Global carrier EMA1561 / exact inference','protocol':'Repeated 57-image development fold, one seed, 113-real training; no all 170 refit','miou':d['summary']['all']['miou'],'note':f"Delta {d['delta']:+.6f}; minority guard {d['minority_guard']}; per-bucket regressions retained in report."})
        receipt=results/'base-candidate/submission/server_receipt.json'
        if receipt.exists():
            r=json.loads(receipt.read_text());response=r['response'];lines+=['','## Leaderboard response','',f"Actual HTTP status: {r['http_status']}; response: `{json.dumps(response)}`."]
            if r['http_status']==200 and response.get('status')=='success':atomic_json(receipt.with_name('upload_receipt.json'),dict(r,response=json.dumps(response)))
    else:lines+=['Checkpoint verification is pending. No new validation score or leaderboard gain is claimed.']
    p=results/'screen-v1/evaluation.json'
    if p.exists():
        d=json.loads(p.read_text());lines+=['','## Single scorer fit / final evaluation','',d['protocol'],'','| Variant | mIoU | Delta vs strongest base | Paired95% CI |','|---|---:|---:|---|',f"| Base | {d['base']['all']['miou']:.6f} | — | — |"]
        for name,v in d['variants'].items():
            lines.append(f"| {name} | {v['summary']['all']['miou']:.6f} | {v['delta_vs_base']:+.6f} | {v['ci95_vs_base']} |")
            measure.append({'family':'pixelseal','name':'PCMV '+name,'protocol':'One 57-image developmental fold, inner action calibration, final evaluation','miou':v['summary']['all']['miou'],'note':f"Delta {v['delta_vs_base']:+.6f}; anti-shortcut{v['anti_shortcut']}"})
        lines+=['',f"Exact one/two-disjoint-toggle oracle (GT-only diagnostic): {d['one_toggle_oracle_miou']:.6f} / {d['two_toggle_oracle_miou']:.6f}. Deployment allows at most one toggle. Candidate for further inference: {d['candidate_for_further_inference']}. Full buckets, miss counts, actions and wrong-message swap are saved in evaluation.json. The wrong-message test holds the existing base/proposals fixed; it tests only new message features."]
        lines+=['','## Why there was no gain','','Both scorers selected threshold 1.0 and applied zero toggles on the 57 validation images and 400 final control views. For ControlB the admissible calibration thresholds were 0.02 and above; for PCMV they were 0.08 and above. All admissible settings tied at calibration mIoU 0.737850, and the predeclared conservative tie break selected no-op. Lower thresholds violated the calibration safety limits; their validation performance was not used to retune the rule.','', 'Zero false toggles and unchanged wrong-message scores are therefore trivial consequences of no-op, not evidence that the verifier can localize a watermark. The result rejects this trained scorer and recipe; it does not prove that all region-level evidence is unusable.','', 'There are two distinct limitations. The proposal bank itself has limited tiny-region coverage (none of 7 tiny foreground images has a proposal reaching minority IoU 0.5). Separately, the scorer did not find an action policy that improved inner calibration while satisfying clean/full-image controls. Calibration images were seen by the base model: their 0.737850 baseline is much higher than 0.581724 on the held-out fold. This in-sample feature/calibration gap is a limitation, not an independently established causal explanation.','', '## Final minority metrics','', '| Group | n | Metric | Base | PCMV | Complete misses base / PCMV |','|---|---:|---|---:|---:|---|']
        for g,k,miss in [('fg_le1','fg_iou','fg_miss'),('fg_1to5','fg_iou','fg_miss'),('fg_5to20','fg_iou','fg_miss'),('fg_gt20','fg_iou','fg_miss'),('clean_le1','clean_iou','clean_miss'),('clean_1to5','clean_iou','clean_miss'),('wm_over50','clean_iou','clean_miss')]:
            b=d['base'][g];v=d['variants']['pcmv']['summary'][g];lines.append(f"| {g} | {v['n']} | {k} | {b[k]:.6f} | {v[k]:.6f} | {b[miss]} / {v[miss]} |")
        lines+=['','## Actual exposure and cost','',f"Scorer training: {d['train_images']} image views (90 real + 260 existing synthetic partial + 64 clean/full controls), {d['proposal_train_examples']:,} proposals, two action targets per proposal. Two predeclared variants, each with two 220-iteration regressors; no repeated endpoint search. Fitting and final evaluation took {d['seconds_fit_evaluate']:.2f}s. The GPU feature job took 21 min 21 s wall time, using only physical GPUs 0/1; base audit used an earlier 85 s job. Repairs ran concurrently and are not added again to wall time.", '', 'Feature generation covered 958 views total: 170 real, 260 synthetic partial, 128 training/calibration controls, 400 final audit controls. The final 400 controls are 200 message/cover realization pairs over 128 distinct dev photos. Full-image control embedding was repeated for the native512 supplement (528 embedding calls,264 distinct realizations); the partial images reuse exact original encodings. Original embedders, strengths, uint8 rounding and inference payloads were unchanged.','', 'The initial CPU attempt failed before any regressor fit because metadata shadowed the numeric base map. Signed uint8 arithmetic in new real-message features was also repaired before fitting. All 170 real features were recomputed with unchanged masks/base predictions; regression checks and repair receipts are archived. The accepted #3188 prediction path always cast bits to float and was unaffected. A fit lock prevented the early CPU request and final worker callback from training twice.','', 'No further PCMV training, test inference or leaderboard submission is justified by this screen. The best deployed pipeline remains #3188 / public 0.6736. The Slurm allocation completed and was released. [Validation gallery of the deployed PixelSeal improvement and failures](GALLERY.md).']
    else:lines+=['','PCMV fitting/evaluation has not completed. Source implementation and planned budget are not measured results.']
    lines+=['','## Scope and safeguards','','See PROTOCOL.md for the frozen screening budget and SOURCES.md for pinned official implementation references. SAM2 resizing is restricted to geometry proposals. Official watermark decoder probes retain original 512 coordinates, exact uint8 replacement bytes and the original decoder preprocessing. Counterfactual boundaries may introduce distribution shifts; scores are learned features, not calibrated Gaussian significance. No GT enters proposal generation or feature extraction. Prior submissions and checkpoints remain preserved.']
    (root/'REPORT.md').write_text('\n'.join(lines)+'\n');atomic_json(results/'measurements.json',measure)


if __name__=='__main__':main()
